static inline int atomic_add_return(int i, volatile atomic_t *v) /* <=== atomic_add_return */ 
{
	unsigned long flags;
	int retval;
	cris_atomic_save(v, flags);
	retval = (v->counter += i);
	cris_atomic_restore(v, flags);
	return retval;
}

static inline void atomic_inc(atomic_t *v) /* <=== atomic_inc */ 
{
	asm volatile(LOCK_PREFIX "incl %0"
		     : "+m" (v->counter));
}

static inline void atomic_inc(volatile atomic_t *v) /* <=== atomic_inc */ 
{
	unsigned long flags;
	cris_atomic_save(v, flags);
	(v->counter)++;
	cris_atomic_restore(v, flags);
}

static inline sector_t get_dev_size(struct block_device *bdev) /* <=== get_dev_size */ 
{
	return i_size_read(bdev->bd_inode) >> SECTOR_SHIFT;
}

static sector_t get_dev_size(struct dm_dev *dev) /* <=== get_dev_size */ 
{
	return i_size_read(dev->bdev->bd_inode) >> SECTOR_SHIFT;
}

static struct pstore *get_info(struct dm_exception_store *store) /* <=== get_info */ 
{
	return (struct pstore *) store->context;
}

static inline int atomic_add_return(int i, atomic_t *v) /* <=== atomic_add_return */ 
{
	unsigned long val;

	asm("0:						\n"
	    "	orcc		gr0,gr0,gr0,icc3	\n"	/* set ICC3.Z */
	    "	ckeq		icc3,cc7		\n"
	    "	ld.p		%M0,%1			\n"	/* LD.P/ORCR must be atomic */
	    "	orcr		cc7,cc7,cc3		\n"	/* set CC3 to true */
	    "	add%I2		%1,%2,%1		\n"
	    "	cst.p		%1,%M0		,cc3,#1	\n"
	    "	corcc		gr29,gr29,gr0	,cc3,#1	\n"	/* clear ICC3.Z if store happens */
	    "	beq		icc3,#0,0b		\n"
	    : "+U"(v->counter), "=&r"(val)
	    : "NPr"(i)
	    : "memory", "cc7", "cc3", "icc3"
	    );

	return val;
}

static inline loff_t i_size_read(const struct inode *inode) /* <=== i_size_read */ 
{
#if BITS_PER_LONG==32 && defined(CONFIG_SMP)
	loff_t i_size;
	unsigned int seq;

	do {
		seq = read_seqcount_begin(&inode->i_size_seqcount);
		i_size = inode->i_size;
	} while (read_seqcount_retry(&inode->i_size_seqcount, seq));
	return i_size;
#elif BITS_PER_LONG==32 && defined(CONFIG_PREEMPT)
	loff_t i_size;

	preempt_disable();
	i_size = inode->i_size;
	preempt_enable();
	return i_size;
#else
	return inode->i_size;
#endif
}

static inline void atomic_inc(atomic_t *v) /* <=== atomic_inc */ 
{
	atomic_add_return(1, v);
}

static inline int atomic_add_return(int i, atomic_t *v) /* <=== atomic_add_return */ 
{
	return i + xadd(&v->counter, i);
}

